46	 * Name: uart_xmitchars
47	 *
48	 * Description:
49	 *   This function is called from the UART interrupt handler when an
50	 *   interrupt is received indicating that there is more space in the
51	 *   transmit FIFO.  This function will send characters from the tail of
52	 *   the xmit buffer while the driver write() logic adds data to the head
53	 *   of the xmit buffer.
54	 *
55	 ****************************************************************************/
56	
57	void uart_xmitchars(FAR uart_dev_t *dev)
58	{
59	  uint16_t nbytes = 0;
60	
61	#ifdef CONFIG_SMP
62	  irqstate_t flags = enter_critical_section();
63	#endif
64	
65	  /* Send while we still have data in the TX buffer & room in the fifo */
66	
67	  while (dev->xmit.head != dev->xmit.tail && uart_txready(dev))
68	    {
69	      /* Send the next byte */
70	
71	      if (dev->ops->sendbuf)
72	        {
73	          ssize_t sent;
74	
75	          if (dev->xmit.tail < dev->xmit.head)
76	            {
77	              sent = dev->xmit.head - dev->xmit.tail;
78	            }
79	          else
80	            {
81	              sent = dev->xmit.size - dev->xmit.tail;
82	            }
83	
84	          sent = uart_sendbuf(dev,
85	                              &dev->xmit.buffer[dev->xmit.tail],
86	                              sent);
87	          if (sent > 0)
88	            {
89	              dev->xmit.tail += sent;
90	              nbytes += sent;
91	            }
92	        }
93	      else
94	        {
95	          uart_send(dev, dev->xmit.buffer[dev->xmit.tail++]);
96	          nbytes++;
97	        }
98	
99	      /* Increment the tail index */
100	
101	      if (dev->xmit.tail >= dev->xmit.size)
102	        {
103	          dev->xmit.tail = 0;
104	        }
105	    }
106	
107	  /* When all of the characters have been sent from the buffer disable the TX
108	   * interrupt.
109	   *
110	   * Potential bug?  If nbytes == 0 && (dev->xmit.head == dev->xmit.tail) &&
111	   * dev->xmitwaiting == true, then disabling the TX interrupt will leave
112	   * the uart_write() logic waiting to TX to complete with no TX interrupts.
113	   * Can that happen?
114	   */
115	
116	  if (dev->xmit.head == dev->xmit.tail)
117	    {
118	      uart_disabletxint(dev);
119	    }
120	
121	  /* If any bytes were removed from the buffer, inform any waiters that
122	   * there is space available.
123	   */
124	
125	  if (nbytes)
126	    {
127	      uart_datasent(dev);
128	    }
129	
130	#ifdef CONFIG_SMP
